import pandas as pd,numpy as np
def reg(f):
    d=pd.read_csv(f); t=d.time_s.values
    P=d.active_power_pu.values; Q=d.reactive_power_pu.values; V=d.voltage_pu.values; th=d.bus_angle_rad.values; S=d.voltage_setpoint_pu.values
    w=np.gradient(th,t[1]-t[0])
    X=np.column_stack([V-V[0],th-th[0],w,S-S[0],np.ones_like(t)])
    for name,y in [('P',P-P[0]),('Q',Q-Q[0])]:
        c,res,_,_=np.linalg.lstsq(X[::10],y[::10],rcond=None)
        print(f,name,np.round(c,5), 'rms y',np.std(y).round(5),'rms resid',np.std(y[::10]-X[::10]@c).round(5))
for f in ['train/A3_amb_op1.csv','train/A3_vref_op1.csv','train/A3_gentrip_op1.csv','train/A3_load_op2.csv']: reg(f)

